import{z as B,x as A,o as l,c as p,q as i,j as n,D as e,d as E,s as o,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"量化误差与剪枝的分工","description":"","frontmatter":{"title":"量化误差与剪枝的分工","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/quantization-vs-prune.md","filePath":"llm/quantization-vs-prune.md","lastUpdated":1791413859000}'),d={name:"llm/quantization-vs-prune.md"};function m(h,a,u,D,c,f){const r=A("Mermaid");return l(),p("div",null,[a[2]||(a[2]=i('<h1 id="量化误差与剪枝的分工" tabindex="-1">量化误差与剪枝的分工 <a class="header-anchor" href="#量化误差与剪枝的分工" aria-label="Permalink to &quot;量化误差与剪枝的分工&quot;">​</a></h1><div class="epigraph"><p>量化管的是每个还在的数用几 bit 表示；剪枝管的是哪些数根本不必存在。两者都降流量，但破坏的几何不同，不能把压缩比加起来当独立因子。</p><footer>—— 对照权重量化（GPTQ 等）与结构化 / 非结构化剪枝；投机草稿是第三条轴，上一压缩课已写</footer></div><p><a href="/llm/why-activation-outliers">激活离群值</a> 解释了量化为何在少数通道上失败。<a href="/llm/structured-prune">结构化剪枝</a>、<a href="/llm/unstructured-sparsity">非结构化稀疏</a>、<a href="/llm/layer-prune">层剪</a> 已经分别讲过删什么。本课写 <strong>分工</strong>：同一预算下先剪还是先量化、误差如何叠加、以及离群维应该被剪掉还是被更高比特保护。不要重讲 INT4 网格或 N:M 稀疏核，只补「两条误差不是正交的」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>量化误差来自离散格子：\\(\\tilde W=q^{-1}(q(W))\\)，函数连续但有台阶，离群决定格子尺度。剪枝误差来自硬零：把坐标或通道或层置零，函数的支撑变小。先量化再按量化后的幅度剪，剪的是格子上的幻影；先剪再量化，幸存权重的动态范围会变，离群集合会变。顺序改变最终网络，不是实现细节。</p><p>压缩比宣传常把「4bit × 50% 稀疏」写成 8×。核与加速器上，非结构稀疏很少吃满理论值，量化也有 scale 开销；更严重的是质量：两次有损靠近同一功能维时，误差相关，总损失大于分开评估之和。分工问题是： <strong>哪一种误差更适合哪一种冗余</strong>。</p><p><span class="marginnote">数字实例：INT4 理论 4×，算上 scale 元数据约 3.8×；50% 非结构稀疏在没有稀疏核的通用 GPU 上往往只兑现 1.2-1.5×。相乘远不到宣传的 8×，而质量损失却是实打实叠加的。</span></p><h3 id="两种冗余" tabindex="-1">两种冗余 <a class="header-anchor" href="#两种冗余" aria-label="Permalink to &quot;两种冗余&quot;">​</a></h3><p>幅度连续、方向重要的参数：适合量化（保留方向、粗化幅度）。接近恒等、通道可删、层可跳的结构：适合剪枝（支撑变小、剩下的仍用较高精度）。离群功能维属于前者里的麻烦子类——幅度既重要又极端，量化伤它，剪枝更伤它，只能留高精度孤岛。<a href="/llm/draft-as-compression">投机草稿</a> 属于第三条：不改 \\(p\\) 的权重，压缩串行步。三轴可以叠，但验收必须在<strong>最终联合图</strong>上做，不能把三篇论文的加速比相乘。<span class="marginnote">QAT 把量化台阶引进训练，剪枝的 mask 若同时学，优化器会把质量塞进幸存且对台阶鲁棒的方向。这比「训完再剪再量化」更一致，也更贵。事后压缩则必须选一个主刀：通常先结构剪（改形状、让核变简单），再量化（改 bit），最后才考虑非结构稀疏吃带宽。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="事后压缩的推荐顺序" tabindex="-1">事后压缩的推荐顺序 <a class="header-anchor" href="#事后压缩的推荐顺序" aria-label="Permalink to &quot;事后压缩的推荐顺序&quot;">​</a></h3><p>推荐顺序（事后压缩）：</p><ol><li>层剪 / 结构化通道剪：改计算图与 KV 层数，收益直接落在 decode 延迟。</li><li>再测离群；对功能维做逐通道平滑或混合精度。</li><li>权重量化（GPTQ / AWQ 一类）+ 激活量化若需要。</li><li>非结构稀疏只在有稀疏核且前三步之后仍欠带宽时加。</li><li>投机草稿独立叠加，目标模型用上面的压缩图。</li></ol><p>联合搜索（每个块选「剪这一层 vs 把这一层 4bit」）更优但组合爆炸。启发式：串行瓶颈（深度）优先剪；并行瓶颈（宽、权重流量）优先量化。Decode 延迟几乎线性于层数，所以服务场景层剪往往先于把所有层打到 3bit。</p>',14)),(l(),n(s,null,{default:e(()=>[o(r,{id:"mermaid-64",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E8%AF%8A%E6%96%AD%E7%A6%BB%E7%BE%A4%E4%B8%8E%E5%B1%82%E5%86%97%E4%BD%99%22%5D%20--%3E%20SP%5B%22%E7%BB%93%E6%9E%84%E5%89%AA%20%2F%20%E5%B1%82%E5%89%AA%22%5D%0A%20%20SP%20--%3E%20SM%5B%22%E5%B9%B3%E6%BB%91%E6%88%96%E9%AB%98%E7%B2%BE%E5%BA%A6%E5%AD%A4%E5%B2%9B%22%5D%0A%20%20SM%20--%3E%20Q%5B%22%E6%9D%83%E9%87%8D%E9%87%8F%E5%8C%96%22%5D%0A%20%20Q%20--%3E%20NS%5B%22%E5%8F%AF%E9%80%89%E9%9D%9E%E7%BB%93%E6%9E%84%E7%A8%80%E7%96%8F%22%5D%0A%20%20Q%20--%3E%20SD%5B%22%E5%8F%AF%E9%80%89%E6%8A%95%E6%9C%BA%E8%8D%89%E7%A8%BF%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"量化保持支撑，近似是局部的：小权重扰动。剪枝是非局部的：整通道消失，下游层看见的表示缺了一块，可能逼出新的离群（补偿）。所以剪完必须重新校准量化统计，不能复用剪前的 SmoothQuant \\(\\sigma\\)。这是误差非正交的具体机制。",-1)),a[5]||(a[5]=t("p",null,"激活量化对离群敏感，权重量化对列 / 通道离群敏感。剪掉「几乎恒等」的层，激活幅度沿深度的分布会变，W8A8 的标定作废。任何改图操作之后，量化校准集要重跑。把校准当一次性手续，是联合压缩最常见的事故。",-1)),(l(),n(s,null,{default:e(()=>[o(r,{id:"mermaid-74",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%89%AA%E6%8E%89%E6%95%B4%E9%80%9A%E9%81%93%20%2F%20%E6%95%B4%E5%B1%82%22%5D%20--%3E%20GAP%5B%22%E4%B8%8B%E6%B8%B8%E7%9C%8B%E5%88%B0%E7%9A%84%E8%A1%A8%E7%A4%BA%E7%BC%BA%E4%B8%80%E5%9D%97%22%5D%0A%20%20GAP%20--%3E%20COMP%5B%22%E5%B9%B8%E5%AD%98%E6%9D%83%E9%87%8D%E8%A1%A5%E5%81%BF%EF%BC%8C%E6%BF%80%E6%B4%BB%E5%88%86%E5%B8%83%E6%94%B9%E5%8F%98%22%5D%0A%20%20COMP%20--%3E%20NEW%5B%22%E5%82%AC%E5%87%BA%E6%96%B0%E7%A6%BB%E7%BE%A4%22%5D%0A%20%20NEW%20--%3E%20STALE%5B%22%E5%89%AA%E5%89%8D%E4%BC%B0%E7%9A%84%E5%B9%B3%E6%BB%91%E5%B0%BA%E5%BA%A6%E4%BD%9C%E5%BA%9F%22%5D%0A%20%20STALE%20--%3E%20FIX%5B%22%E5%BF%85%E9%A1%BB%E9%87%8D%E8%B7%91%E6%A0%A1%E5%87%86%EF%BC%8C%E4%B8%8D%E8%83%BD%E5%A4%8D%E7%94%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">直觉类比：剪枝像拆掉流水线上的整道工序，下游工人必须换姿势补活（补偿），原先调好的参数全要重标；量化只是把每个零件的刻度变粗，工序本身没动。这就是为什么剪完必须重新校准。</span></p><p><span class="marginnote">蒸馏小模型与剪枝竞争同一预算：与其把 70B 剪到质量不可用，不如蒸馏到 8B 再量化。草稿压缩课写过质量由目标 \\(p\\) 兜底的情况；这里没有兜底——剪和量化都改 \\(p\\) 本身。不要用投机的无损承诺来安慰权重量化。</span></p><h3 id="何时量化优于剪" tabindex="-1">何时量化优于剪 <a class="header-anchor" href="#何时量化优于剪" aria-label="Permalink to &quot;何时量化优于剪&quot;">​</a></h3><p>需要保持架构接口（张量并行切分、现成核、LoRA 形状）时，量化不改形状，部署更便宜。当加速器没有低比特核、却有结构化稀疏或更少层的收益时，剪更值。边缘设备内存硬顶，两者都要，仍应按上面顺序，并用一套下游集看联合误差，包括长上下文——离群与 KV 量化在长序列上才充分暴露。<span class="marginnote">术语翻译：LoRA 形状指挂在冻结权重旁的低秩增量矩阵的尺寸。量化不动 \\(W\\) 的形状，LoRA 原样能挂；剪掉通道后形状全变，适配器得重做甚至重训——这是「接口敏感场景优先量化」的实义。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>MoE 上剪路由专家等于改配比 \\(\\rho\\)；量化共享专家伤全局。分工还带架构语义，不是通用套件。视觉前缀、音频码的量化网格应与文本分开，早融合序列里一块 INT4 会让 OCR 先死、聊天还在。</p><p>评测不要只用短 CE。剪层伤深度依赖，量化伤精细幅度（算术、格式）。分开看两项指标，才能知道下一步该剪还是该回退 bit。联合压缩的论文数字若只报平均值，会隐藏「数学崩了、聊天还行」。</p><p><span class="marginnote">金融里的「量化」在本站是微观结构课，与权重量化无关。本课只在 LLM 压缩单元里使用该词。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>量化粗化还在的数；剪枝删除支撑；投机压缩目标模型的步数。三轴误差相关。</li><li>事后压缩宜先改图（结构剪），再处理离群，再量化，稀疏与草稿最后叠加。</li><li>剪完必须重校准量化统计；新离群会补偿出现。</li><li>功能离群维留精度，不要剪也不要挤进 3bit。</li><li>验收用联合图与分能力指标，禁止加速比连乘。</li><li>出处：GPTQ / AWQ / SmoothQuant 与结构化剪枝、层剪的工程顺序。</li></ul>',10))])}const T=B(d,[["render",m]]);export{P as __pageData,T as default};
